          // key interval.
          entryInterval = null;
        }
      }
    } else if (versionCompare > 0) {
      // since the entry version is greater than the existing one, the given entry overwrites the existing one
      // if overlapped.
      final TimelineEntry oldEntry = timeline.remove(currKey);

